#requires -Version 5.1
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
$root=Join-Path $PSScriptRoot 'common\src\main\resources\assets\akaishi\textures\block'
$previewDir=Join-Path $PSScriptRoot 'gui_layouts'; New-Item -ItemType Directory -Force $previewDir | Out-Null
function Fill($g,$x,$y,$w,$h,$c){$b=New-Object Drawing.SolidBrush([Drawing.ColorTranslator]::FromHtml($c));try{$g.FillRectangle($b,$x,$y,$w,$h)}finally{$b.Dispose()}}
function Paint($name,$face,$accent){$bmp=New-Object Drawing.Bitmap(64,64);$g=[Drawing.Graphics]::FromImage($bmp);try{$g.Clear([Drawing.Color]::FromArgb(255,18,23,29));Fill $g 2 2 60 60 '#71808A';Fill $g 5 5 54 54 '#202C34';Fill $g 8 8 48 48 '#354854';if($face -eq 'top'){Fill $g 13 13 38 38 '#0E171E';Fill $g 18 18 28 28 $accent;Fill $g 23 23 18 18 '#263C43';Fill $g 29 21 6 4 '#D9FFF0'}elseif($face -eq 'bottom'){for($x=12;$x -lt 54;$x+=8){Fill $g $x 12 3 40 '#B8C4C8';Fill $g ($x+3) 12 2 40 '#17232B'}}else{Fill $g 12 13 40 36 '#0E171E';Fill $g 17 18 30 26 $accent;Fill $g 23 23 18 14 '#263C43';Fill $g 29 25 6 10 '#D9FFF0';for($x=17;$x -lt 49;$x+=8){Fill $g $x 50 4 3 $accent}}Fill $g 5 5 3 3 '#E1EAEC';Fill $g 56 5 3 3 '#E1EAEC';Fill $g 5 56 3 3 '#E1EAEC';Fill $g 56 56 3 3 '#E1EAEC';$path=Join-Path $root ($name+'_'+$face+'.png');$bmp.Save($path,[Drawing.Imaging.ImageFormat]::Png);return $bmp}finally{$g.Dispose()}}
$targets=@(@('akaishi_item_reconstructor','#57C7C4'),@('akaishi_plant_cultivator','#68B96B'),@('akaishi_cultivator','#55AFA0'),@('akaishi_surgery','#D65D7A'),@('akaishi_trait_reforger','#A66BD1'),@('akaishi_upgrade_station','#D29B49'),@('akaishi_potion_table','#6B8FE3'),@('akaishi_potion_cabinet','#8767B6'),@('akaishi_sample_vault','#52B8A0'),@('akaishi_organ_vault','#C85D78'))
foreach($t in $targets){$faces=@();foreach($f in @('top','side','bottom')){$b=Paint $t[0] $f $t[1];$faces+=$b};$sheet=New-Object Drawing.Bitmap(212,76);$sg=[Drawing.Graphics]::FromImage($sheet);try{$sg.Clear([Drawing.Color]::FromArgb(255,10,14,18));for($i=0;$i -lt 3;$i++){$sg.DrawImageUnscaled($faces[$i],(4+$i*70),6)}$sheet.Save((Join-Path $previewDir ($t[0]+'_batch_preview.png')),[Drawing.Imaging.ImageFormat]::Png)}finally{$sg.Dispose();$sheet.Dispose();$faces|% Dispose}}
Write-Output 'SUCCESS: painted 30 native 64x64 textures and 10 named previews; JSON untouched.'